import{STAGES,SCENES,TREASURE_SCENES,SAVE_KEY,distance,walkable,findPath,validSave,makeSave,unlockedScenes,bonusReady}from './engine.js';
import{World}from './world.js';
import{createPuzzles}from './puzzles.js';
import{GameAudio}from './audio.js';
import{MoviePlayer}from './movies.js';
const $=s=>document.querySelector(s),world=new World($('#world'));
$('#start').disabled=true;
world.ready.then(results=>{if(results.every(Boolean))$('#start').disabled=false;else{toast('部分场景尚未载入，请刷新页面再试。');$('#start').textContent='场景载入失败，请刷新';}});
const state={started:false,ending:false,cinematic:null,storyPending:null,endingPending:false,introPending:false,completionVideoPending:false,stage:0,scene:'city',player:{x:300,y:860},elapsed:0,empathy:false,collectibles:[],treasures:[],records:{},completed:false,bonusSeen:false,path:[],moving:false,facing:'down'};
let replay=false,pendingChest=false;
let keys=new Set(),joystick={x:0,y:0},modalOpen=false,paused=false,hidden=document.hidden,puzzleTick=null,puzzleKeys=null,lastTime=0,toastTimer,lastSave=0,pauseFragment=null;
const ui={hud:$('#hud'),controls:$('#play-controls'),modal:$('#modal'),backdrop:$('#modal-backdrop'),title:$('#title-screen')};
const audio=new GameAudio({music:$('#background-music'),onChange:(enabled,message)=>{updateSound();if(message)toast(message);}});
const movie=new MoviePlayer({overlay:$('#movie-overlay'),video:$('#story-video'),poster:$('#movie-poster'),title:$('#movie-title'),status:$('#movie-status'),play:$('#movie-play'),skip:$('#movie-skip'),onActive(active){keys.clear();resetJoy();state.path=[];state.moving=false;audio.block('movie',active);for(const el of [...$('#game-frame').children])if(el!==$('#movie-overlay'))el.inert=active;},onPause(value){audio.block('movie-pause',value);}});
function updateSound(){const enabled=audio.enabled;$('#sound').innerHTML=`♪<span>${enabled?'开':'关'}</span>`;if($('.modal-sound'))$('.modal-sound').textContent=enabled?'♪ 声音开':'♪ 声音关';for(const b of [$('#sound'),$('#movie-sound'),...document.querySelectorAll('.modal-sound')]){b.setAttribute('aria-label',enabled?'关闭声音':'开启声音');b.setAttribute('aria-pressed',String(enabled));}$('#movie-sound').textContent=enabled?'♪ 开':'♪ 关';$('#story-video').muted=!enabled;}
$('#sound').onclick=$('#movie-sound').onclick=()=>audio.toggle();updateSound();
function sound(name,volume){audio.effect(name,volume);}
function playIntro(){movie.show('intro',()=>{state.introPending=false;save();introDialogue();});}
function introDialogue(){dialogue([['玉兔','嫦娥！月亮不见了！水岸上只剩下几缕月光……'],['嫦娥','小拓，出发！先到城市终端规划航线。已到访的区域，可以随时通过「行旅」回去。']],()=>toast('方向键 / WASD 移动，E 互动；也可点击地面或拖动摇杆。'));}
function finishMoonReturn(){if(bonusReady(state)&&!state.bonusSeen)bonusStory();else reunionStory(false);}
function playCompletion(){movie.show('completion',()=>{state.completionVideoPending=false;save();finishMoonReturn();});}
function modalSound(){const b=document.createElement('button');b.className='modal-sound';b.onclick=()=>audio.toggle();ui.modal.prepend(b);updateSound();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function save(){if(!state.started)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(makeSave(state.stage,state.player,state.elapsed,state.empathy,state.collectibles,{scene:state.scene,treasures:state.treasures,records:state.records,completed:state.completed,bonusSeen:state.bonusSeen,endingPending:state.endingPending,storyPending:state.storyPending,introPending:state.introPending,completionVideoPending:state.completionVideoPending})));$('#save-status').textContent='进度已保存';}catch{$('#save-status').textContent='当前浏览器无法保存进度';}}
function loadSave(){try{return validSave(JSON.parse(localStorage.getItem(SAVE_KEY)));}catch{return null;}}
if(loadSave())$('#continue').hidden=false;
function updateUI(){const task=STAGES[state.stage];$('#quest-text').textContent=state.completed?'月已归天 · 自由探索':task.scene===state.scene?task.title:`前往${SCENES[task.scene].name}继续任务`;$('#quest-tag').textContent=state.completed?'旅程完成':state.stage>=6?'主线任务 · 补全团圆':'主线任务 · 找回月亮';$('#quest-count').textContent=`${state.stage+1}/11`;$('#interact b').textContent=state.scene===task.scene&&!state.completed?task.action:'互动';$('#location-tag').textContent=SCENES[state.scene].name;$('#chapter-number').textContent=`第${['一','二','三','四'][task.chapter]}章`;$('#chapter-name').textContent=['循光入城','一轮借来的月亮','造一束月光','两处皆团圆'][task.chapter];document.querySelectorAll('#chapters li').forEach((el,i)=>{el.classList.toggle('active',i===task.chapter);el.classList.toggle('done',i<task.chapter);el.querySelector('i').textContent=i<task.chapter?'✓':'◇';});}
function clearPuzzle(){puzzleTick=null;puzzleKeys=null;audio.setLoop(null);audio.stopEffects();}
function openModal(html){clearPuzzle();state.path=[];keys.clear();joystick={x:0,y:0};ui.modal.innerHTML=html;modalSound();ui.backdrop.classList.toggle('story-scene',!!state.cinematic);ui.backdrop.classList.toggle('painting-scene',state.cinematic==='painting');ui.backdrop.hidden=false;modalOpen=true;ui.controls.hidden=true;ui.modal.scrollTop=0;ui.modal.focus();}
function closeModal(){clearPuzzle();ui.backdrop.hidden=true;modalOpen=false;paused=false;audio.block('pause',false);ui.controls.hidden=!state.started||state.ending;keys.clear();$('#world').focus({preventScroll:true});}
function header(kicker,title,text=''){return `<div class="eyebrow">${kicker}</div><h2 id="modal-title">${title}</h2>${text?`<p>${text}</p>`:''}`;}
function dialogue(lines,done,finalLabel='我明白了'){let i=0;function show(){const [speaker,text]=lines[i],portrait={'小拓':0,'吴刚':1,'画中孩子':2,'玉兔':3,'嫦娥':'change'}[speaker],cinematic=state.cinematic,kicker=cinematic?({reward:'玉兔赠饼',reunion:'月下团圆',water:'石桥重现',museum:'设备送达',painting:'画中团圆'}[cinematic]||'月下相逢'):speaker==='嫦娥'?'远程通讯':'月下相逢';openModal(`<div class="dialogue-person">${portrait!==undefined?`<div class="portrait portrait-${portrait}" role="img" aria-label="${speaker}的形象"></div>`:''}<div>${header(kicker,speaker)}</div></div><div class="dialogue-text">${text}</div><button class="gold-button" id="next-dialogue">${i===lines.length-1?finalLabel:'继续'} <span>→</span></button>`);$('#next-dialogue').onclick=()=>{if(++i<lines.length)show();else{closeModal();done?.();}sound('ui_confirm');};}show();}
function travel(scene){pendingChest=false;state.cinematic=null;state.scene=scene;state.player={...SCENES[scene].spawn};state.path=[];state.moving=false;updateUI();save();}
function go(stage,message){state.stage=stage;travel(STAGES[stage].scene);if(message)toast(message);}
function begin(resume=false){const old=resume?loadSave():null;Object.assign(state,{started:true,ending:false,cinematic:null,storyPending:null,endingPending:false,introPending:false,completionVideoPending:false,stage:0,scene:'city',player:{x:300,y:860},elapsed:0,empathy:false,collectibles:[],treasures:[],records:{},completed:false,bonusSeen:false,path:[]},old||{});replay=false;pendingChest=false;state.introPending=old?state.introPending:true;paused=false;audio.start();lastSave=state.elapsed;ui.title.hidden=true;$('#ending').hidden=true;ui.hud.hidden=false;ui.controls.hidden=false;updateUI();save();if(state.introPending)playIntro();else if(state.completionVideoPending)playCompletion();else if(state.storyPending)playPendingStory();else if(bonusReady(state)&&!state.bonusSeen)bonusStory();else if(state.endingPending)reunionStory(false);else if(old)toast('欢迎回来，小拓。我们接着追月。');else introDialogue();}
$('#start').onclick=()=>{if(loadSave()){openModal(`${header('新的冒险','重新开始追月？','当前设备已有一段旅程。重新开始会替换这份进度。')}<button class="gold-button" id="new-confirm">重新开始</button><button class="secondary-button" id="keep-save">继续原来的旅程</button>`);$('#new-confirm').onclick=()=>{closeModal();begin();};$('#keep-save').onclick=()=>{closeModal();begin(true);};}else begin();};$('#continue').onclick=()=>begin(true);
const puzzles=createPuzzles({$,state,keys,open:openModal,close:closeModal,header,sound,loop:name=>audio.setLoop(name),isReplay:()=>replay,complete(id,score,next,message){state.records[id]=Math.min(state.records[id]??Infinity,score);if(id==='snake'&&!state.collectibles.includes('city'))state.collectibles.push('city');if(id==='calibration'&&!state.collectibles.includes('moon'))state.collectibles.push('moon');closeModal();if(!replay){const story={water:'drain',flight:'delivery',calibration:'painting'}[id];if(story){state.stage=next;state.storyPending=story;if(id!=='water')travel(STAGES[next].scene);save();playPendingStory();}else go(next,message);}else{save();toast('最佳成绩已保存。');}replay=false;},setTick:fn=>puzzleTick=fn,setKeys:fn=>puzzleKeys=fn});
function interact(){
 if(!state.started||state.ending||modalOpen||movie.active)return;
 const chest=SCENES[state.scene].chest;
 if(chest&&!state.treasures.includes(state.scene)&&distance(state.player,chest)<36){collectTreasure();return;}
 const task=STAGES[state.stage];
 if(state.scene!==task.scene||state.completed){if(state.scene==='museum')dialogue([['吴刚','月下城还有不少值得驻足的角落。你随时可以回来。']]);else toast('点击地面自由走动，或打开「行旅」前往其他区域。');return;}
 if(distance(state.player,task)>64){toast(`先走近金色标记：${task.label}`);state.path=findPath(state.player,task,state.scene,state.stage);return;}
 replay=false;
 switch(state.stage){
 case 0:puzzles.snake();break;case 1:puzzles.traffic();break;case 2:puzzles.water();break;
 case 3:puzzles.quiz();break;
 case 4:dialogue([['小拓','吴刚，是你把月亮带走了吗？'],['吴刚','借一晚。画里这孩子，好久没见过月亮了。']],choice);break;
 case 5:dialogue([['画中孩子','以前，每到中秋，月光都会照进这个院子。可那里破了以后……'],['小拓','原来，天上的人盼团圆，画里的人也一样。']],()=>{state.empathy=true;if(!state.collectibles.includes('child'))state.collectibles.push('child');save();choice();});break;
 case 6:puzzles.factory();break;case 7:puzzles.assembly();break;case 8:puzzles.flight();break;case 9:puzzles.calibration();break;
 case 10:dialogue([['小拓','天上的还回去，画里的，我们造好了。'],['吴刚','原来，不必让谁失去月亮。谢谢你，小拓。']],()=>endGame(true));sound('moon_return');break;
 }}
$('#interact').onclick=interact;
function collectTreasure(){
 const scene=state.scene;if(!SCENES[scene].chest||state.treasures.includes(scene))return;
 state.path=[];state.treasures.push(scene);save();
 dialogue([['小拓',`${SCENES[scene].note}<br><span class="found-item">获得：${SCENES[scene].ingredient}</span>`]],()=>{sound('item_gain');if(bonusReady(state)&&!state.bonusSeen)bonusStory();});sound('chest_open');
}
function setCinematic(scene){state.cinematic=scene;state.path=[];state.moving=false;pendingChest=false;ui.hud.hidden=true;ui.controls.hidden=true;$('#toast').classList.remove('visible');$('#world').classList.remove('scene-reveal');void $('#world').offsetWidth;$('#world').classList.add('scene-reveal');}
function finishStory(){state.storyPending=null;state.cinematic=null;ui.hud.hidden=false;ui.controls.hidden=false;ui.backdrop.classList.remove('story-scene','painting-scene');travel(STAGES[state.stage].scene);save();}
function playPendingStory(){
 const story=state.storyPending;
 if(story==='drain'){setCinematic('water');dialogue([['小拓','管网接通了！积水退去，刚才被淹住的石板路露出来了。现在可以继续去博物馆。']],finishStory,'沿石桥前往博物馆');sound('water_drain');}
 else if(story==='delivery'){setCinematic('museum');dialogue([['小拓','无人机把立体投影仪送来了。我已把它摆在古画右侧的柜台上。'],['嫦娥','设备已就位。校准光路，让新的月光照进那幅残画。']],finishStory,'走近投影仪，开始校准');sound('drone_land');}
 else if(story==='painting'){setCinematic('painting');dialogue([['画中孩子','爹，娘！月亮亮起来了……我们又能一起过中秋了。'],['小拓','画里的家人终于团聚了。现在，把真正的月亮还给窗外等候的人们吧。']],finishStory,'回到展馆，让真月归位');sound('painting_reveal');}
}
function bonusStory(){if(!bonusReady(state)||state.bonusSeen)return;state.endingPending=true;save();setCinematic('reward');dialogue([['玉兔','桂花、莲蓉、糯米粉……八味食材都齐了！这是特意为你做的团圆月饼。'],['玉兔','给你，谢谢你让天上和画里都有了团圆。嫦娥已经在等我们，走，一起去吧。']],()=>reunionStory(true),'收下月饼，一起赴约');sound('gift_unlock');}
function reunionStory(bonus){setCinematic('reunion');dialogue([['嫦娥','小拓、玉兔，辛苦了。来，大家一起吃月饼吧。'],['小拓',bonus?'月饼里有一路收集的八份心意。这个中秋，我们也团圆了。':'天上有月，画中有光。这个中秋，我们也团圆了。']],()=>{if(bonus)state.bonusSeen=true;state.endingPending=false;save();showEnding(true,bonus);},'一起赏月');}
const challengeList=[['snake','障碍贪吃蛇',0,'格'],['traffic','车阵华容道',1,'格'],['water','旋转管网',2,'次'],['quiz','文博知识问答',3,'题答错'],['factory','能源推箱',6,'步'],['assembly','联动电路',7,'次'],['flight','无人机配送',8,'次碰撞'],['calibration','反射镜光路',9,'次']];
function showTravel(){
 if(modalOpen||!state.started||state.ending||movie.active)return;
 openModal(`${header('月下行旅','再走一程','已到访的地方，可以随时回去。')}<div class="scene-list">${unlockedScenes(state.stage).map(k=>`<button class="scene-link ${k===state.scene?'selected':''}" data-scene="${k}"><span>${SCENES[k].name}</span><small>${k===state.scene?'当前区域':k===STAGES[state.stage].scene&&!state.completed?'任务所在':'前往'}</small></button>`).join('')}</div><h3>再挑战一次</h3><div class="challenge-list">${challengeList.filter(([, ,stage])=>state.stage>stage).map(([id,name,,unit])=>`<button class="secondary-button" data-replay="${id}">${name}<small>${state.records[id]===undefined?'尚无成绩':`最佳 ${state.records[id]} ${unit}`}</small></button>`).join('')||'<p>完成第一项挑战后开放。</p>'}</div>${state.stage>=10?'<button class="secondary-button" id="revisit-painting">重看 · 画中团圆</button>':''}<button class="text-button" id="travel-close">返回场景</button>`);
 $('#travel-close').onclick=closeModal;if($('#revisit-painting'))$('#revisit-painting').onclick=()=>{state.storyPending='painting';save();playPendingStory();};ui.modal.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{closeModal();travel(b.dataset.scene);});ui.modal.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{replay=true;puzzles[b.dataset.replay]();});
}
function showBag(){if(modalOpen||!state.started||state.ending||movie.active)return;openModal(`${header('随身行囊','沿途的心意',state.treasures.length?'玉兔留下的食谱共有八味。':'行囊里，暂时只有一片月光。')}<div class="ingredient-list">${state.treasures.map(k=>`<span>${SCENES[k].ingredient}</span>`).join('')}</div>${state.treasures.length?`<p>已收集 ${state.treasures.length} / 8 味${state.bonusSeen?' · 已尝到团圆月饼':state.treasures.length===TREASURE_SCENES.length?' · 等月亮归位，就去和玉兔分享。':''}</p>`:''}<button class="gold-button" id="bag-close">收好行囊</button>`);$('#bag-close').onclick=closeModal;}
$('#travel').onclick=showTravel;$('#bag').onclick=showBag;
function choice(){openModal(`${header('一个关于团圆的选择','月亮，该回哪里？','桂木灯笼里是真正的月亮。窗外的人们还在等，而画里的孩子也不愿告别。')}<button class="secondary-button" id="take-moon">取回月亮，让它回到天上</button>${state.empathy?'<button class="gold-button" id="both">✦ 让两边都团圆</button><p class="hint">已理解画中孩子的心愿 · 新的解法已解锁</p>':'<button class="gold-button" id="look-painting">先走近古画，听听他的心愿</button><p class="hint">有些答案，要靠近一点才看得见。</p>'}`);$('#take-moon').onclick=()=>dialogue([['吴刚','好吧。天上的月亮，确实该回去了。'],['小拓','月亮回到了夜空。可画里的那一角，还没有亮起来。']],()=>endGame(false));if(state.empathy)$('#both').onclick=()=>{closeModal();go(6,'隐藏解法已解锁：制造一轮属于画中的月亮。');dialogue([['小拓','天上的还回去，画里的，我们来造。'],['嫦娥','工厂已连线。先在孪生仓库里调配能源，再启动实体装配。']]);};else $('#look-painting').onclick=()=>{closeModal();go(5,'从灯笼右侧绕到古画前，按 E 观察。');};}
function endGame(good){
 closeModal();if(good){state.completed=true;state.endingPending=true;state.completionVideoPending=true;save();playCompletion();}else showEnding(false);
}
function showEnding(good,bonus=false){
 state.cinematic=null;state.ending=true;state.path=[];ui.hud.hidden=true;ui.controls.hidden=true;
 $('#ending').hidden=false;
 $('#ending').innerHTML=`<div class="eyebrow">${bonus?'玉兔赠饼 · 隐藏剧情达成':good?'团圆结局达成':'旅程结局'}</div><h2>${bonus?'八味成团圆':good?'两处皆团圆':'明月归天'}</h2><p>${good?'一桌月饼，三位旅伴。<br>今夜的月光，终于照着每一个团圆。':'你找回了天上的月亮。<br>古画中，还有一个等待被照亮的心愿。'}</p><div class="ending-actions"><button class="gold-button" id="ending-action">${good?'留在月下城 · 自由探索':'回到古画 · 寻找另一种解法'}</button><button class="text-button" id="ending-home">保存并返回扉页</button><br><small>本次旅程 ${Math.floor(state.elapsed/60)} 分 ${Math.floor(state.elapsed%60)} 秒 · 凡拓数创 AIR 3D</small></div>`;
 $('#ending-action').onclick=()=>{state.ending=false;$('#ending').hidden=true;ui.hud.hidden=false;ui.controls.hidden=false;if(!good)go(5);else{travel('museum');toast('可以回访各地，也可以在「行旅」里挑战自己的最佳成绩。');}save();};
 $('#ending-home').onclick=()=>{save();state.started=false;audio.block('title',true);state.ending=false;$('#ending').hidden=true;ui.title.hidden=false;$('#continue').hidden=!loadSave();};
 }
function pause(){if(movie.active){movie.pause();return;}if(!state.started||state.ending)return;if(paused){resume();return;}paused=true;audio.block('pause',true);keys.clear();state.path=[];joystick={x:0,y:0};pauseFragment=document.createDocumentFragment();while(ui.modal.firstChild)pauseFragment.append(ui.modal.firstChild);ui.modal.dataset.wasOpen=String(modalOpen);ui.modal.innerHTML=`${header('让月光等一会儿','冒险已暂停','进度已自动保存。准备好后，我们继续。')}<div class="pause-list"><button class="gold-button" id="resume-game">继续冒险</button><button class="secondary-button" id="help-game">查看操作方法</button><button class="secondary-button" id="back-title">保存并返回扉页</button></div>`;modalSound();ui.backdrop.hidden=false;ui.controls.hidden=true;modalOpen=true;$('#resume-game').onclick=resume;$('#help-game').onclick=()=>toast('WASD / 方向键移动，E 互动，Esc 暂停。手机拖动摇杆，点击右侧互动按钮。');$('#back-title').onclick=()=>{save();clearPuzzle();pauseFragment=null;closeModal();state.started=false;audio.block('title',true);state.cinematic=null;ui.backdrop.classList.remove('story-scene','painting-scene');ui.title.hidden=false;ui.hud.hidden=true;ui.controls.hidden=true;$('#continue').hidden=!loadSave();};save();ui.modal.focus();}
function resume(){const wasOpen=ui.modal.dataset.wasOpen==='true';ui.modal.innerHTML='';if(pauseFragment)ui.modal.append(pauseFragment);updateSound();pauseFragment=null;paused=false;audio.unlock();audio.block('pause',false);modalOpen=wasOpen;ui.backdrop.hidden=!wasOpen;ui.controls.hidden=wasOpen;keys.clear();if(wasOpen)ui.modal.focus();else $('#world').focus({preventScroll:true});}
$('#pause').onclick=pause;
document.addEventListener('keydown',e=>{if(movie.active)return;const key=e.key.length===1?e.key.toLowerCase():e.key,movement=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'];if(state.started&&([...movement,'Escape'].includes(key)||key===' '&&document.activeElement?.tagName!=='BUTTON'))e.preventDefault();if(key==='Escape'){if(state.started)pause();return;}if(paused)return;if(modalOpen){if(puzzleKeys){puzzleKeys(key,e.repeat);}else if(key==='Enter'&&!e.repeat&&!['BUTTON','INPUT'].includes(document.activeElement?.tagName))$('#next-dialogue')?.click();if(movement.includes(key))keys.add(key);return;}if(movement.includes(key)){keys.add(key);state.path=[];}if((key==='e'||key===' ')&&!e.repeat)interact();});
document.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!modalOpen||movie.active)return;const els=[...ui.modal.querySelectorAll('button:not(:disabled),a[href],[tabindex="0"]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===ui.modal)){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===ui.modal)){e.preventDefault();first.focus();}});
window.addEventListener('focus',()=>audio.block('window',false));window.addEventListener('blur',()=>{audio.block('window',true);keys.clear();joystick={x:0,y:0};if(state.started&&!state.ending&&!paused)pause();});document.addEventListener('visibilitychange',()=>{hidden=document.hidden;audio.block('hidden',hidden);keys.clear();if(hidden){save();if(state.started&&!state.ending&&!paused)pause();}});window.addEventListener('pagehide',()=>{save();audio.block('hidden',true);});
const joy=$('#joystick'),knob=$('#joy-knob');function resetJoy(){joystick={x:0,y:0};knob.style.transform='';}function joyMove(e){const r=joy.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),scale=Math.min(1,32/(len||1));joystick={x:dx*scale/32,y:dy*scale/32};if(len<8)joystick={x:0,y:0};knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;state.path=[];}joy.onpointerdown=e=>{joy.setPointerCapture(e.pointerId);joyMove(e);};joy.onpointermove=e=>{if(joy.hasPointerCapture(e.pointerId))joyMove(e);};joy.onpointerup=joy.onpointercancel=joy.onlostpointercapture=resetJoy;
$('#world').onpointerdown=e=>{if(modalOpen||!state.started||state.ending||movie.active)return;const r=e.currentTarget.getBoundingClientRect(),point={x:(e.clientX-r.left)/r.width*540,y:(e.clientY-r.top)/r.height*960},task=STAGES[state.stage],chest=SCENES[state.scene].chest;
 if(chest&&!state.treasures.includes(state.scene)&&Math.abs(point.x-chest.x)<22&&point.y>=chest.y-38&&point.y<=chest.y+8){if(distance(state.player,chest)<36)collectTreasure();else{state.path=findPath(state.player,chest,state.scene,state.stage);pendingChest=true;}return;}
 pendingChest=false;if(state.scene===task.scene&&!state.completed&&distance(point,task)<60&&distance(state.player,task)<64){interact();return;}
 const path=findPath(state.player,point,state.scene,state.stage);if(path.length)state.path=path;else toast('这里走不通，试试沿着地面走。');};
function tick(timestamp){const dt=Math.min(.045,(timestamp-lastTime)/1000||0);lastTime=timestamp;if(!hidden){if(state.started&&!state.ending&&!paused&&!movie.active){state.elapsed+=dt;if(modalOpen)puzzleTick?.(dt);else{let dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0)+joystick.x,dy=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0)+joystick.y;const task=STAGES[state.stage];if(!dx&&!dy&&state.path.length){const next=state.path[0],d=distance(state.player,next);if(d<5)state.path.shift();else{dx=(next.x-state.player.x)/d;dy=(next.y-state.player.y)/d;}}const len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len;}state.moving=len>.1;if(state.moving){state.facing=dy<-.2?'up':dy>.2?'down':dx>0?'right':'left';const speed=118*dt,nx=state.player.x+dx*speed,ny=state.player.y+dy*speed;if(walkable(nx,state.player.y,state.scene,state.stage))state.player.x=nx;if(walkable(state.player.x,ny,state.scene,state.stage))state.player.y=ny;}$('#interact').classList.toggle('ready',state.scene===task.scene&&!state.completed&&distance(state.player,task)<64);if(pendingChest&&distance(state.player,SCENES[state.scene].chest)<33){pendingChest=false;collectTreasure();}}if(state.elapsed-lastSave>5){save();lastSave=state.elapsed;}}else state.moving=false;world.draw(state,timestamp/1000);}requestAnimationFrame(tick);}
requestAnimationFrame(tick);
const modelContext=document.modelContext??navigator.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(modelContext.registerTool({name:'moon_chase_progress',description:'Read the current quest and controls for the local Moon Chase game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(input&&Object.keys(input).length)throw new Error('This tool takes no arguments.');return {started:state.started,ending:state.ending,quest:STAGES[state.stage].title,location:state.scene,controls:'WASD or arrow keys move; E interacts; Escape pauses.'};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||movie.active)return;if(b.matches('#travel-close,#bag-close,#leave-puzzle,#undo'))sound('ui_back');else if(b.matches('#travel,#bag,[data-scene],#next-question,#test-flow,#test-light,#take-moon,#both,#look-painting,#ending-action'))sound('ui_confirm');});
